// Skeleton: simulate a DP-guarded update
function dpUpdate(weights, clip, sigma){
  // clip
  let clipped = weights.map(w => Math.max(-clip, Math.min(clip, w)));
  // add noise
  return clipped.map(w => w + randn(0, sigma));
}
```

